target.css:
:root {
  --ink: #25324a;
  --muted: #71809a;
  --paper: #fffdf8;
  --line: #dce2eb;
  --navy: #334d7c;
  --blue-soft: #eaf0fb;
  --gold: #e2a42b;
  --green: #2d9a72;
  --green-soft: #e6f5ee;
}

.rehearsal-card {
  width: 480px;
  box-sizing: border-box;
  overflow: hidden;
  color: var(--ink);
  background: var(--paper);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.card-header {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 16px 12px;
  border-bottom: 1px solid var(--line);
}

.bell-mark {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  font-size: 20px;
  background: var(--blue-soft);
  border-radius: 12px;
}

.title-group {
  flex: 1;
}

.eyebrow {
  margin: 0 0 2px;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.rehearsal-card h1 {
  margin: 0;
  font-size: 21px;
  line-height: 1.1;
}

.status {
  padding: 5px 9px;
  color: var(--green);
  background: var(--green-soft);
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
}

.schedule {
  display: grid;
  grid-template-columns: 104px 1fr;
  gap: 14px;
  margin: 14px 16px;
}

.time-block {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: 12px;
  color: var(--navy);
  background: var(--blue-soft);
  border-radius: 12px;
}

.time-block strong {
  font-size: 22px;
  line-height: 1;
}

.time-block span {
  margin-top: 5px;
  font-size: 12px;
  font-weight: 700;
}

.details {
  padding: 2px 0;
}

.details strong,
.details span,
.details p {
  display: block;
}

.details strong {
  font-size: 15px;
}

.details span {
  margin-top: 3px;
  color: var(--muted);
  font-size: 13px;
}

.details p {
  margin: 8px 0 0;
  color: var(--navy);
  font-size: 13px;
  font-weight: 700;
}

.cue-list {
  display: flex;
  gap: 8px;
  margin: 0;
  padding: 0 16px 14px;
  list-style: none;
}

.cue-list li {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 6px 8px;
  color: var(--muted);
  border: 1px solid var(--line);
  border-radius: 8px;
  font-size: 12px;
}

.note-dot {
  width: 6px;
  height: 6px;
  background: var(--gold);
  border-radius: 50%;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 16px;
  background: var(--blue-soft);
}

.leader {
  color: var(--muted);
  font-size: 12px;
}

.card-footer button {
  padding: 7px 12px;
  color: var(--paper);
  background: var(--navy);
  border: 0;
  border-radius: 8px;
  font-size: 12px;
  font-weight: 700;
}

